def total(n):
    if n == 0:
        return 0
    return total(n - 1) + n


def odd_total(n):
    if n == 1:
        return 1
    return odd_total(n - 1) + (2 * n - 1)


def power_total(n):
    if n == 0:
        return 1
    return power_total(n - 1) + 2 ** n


print("1 + 2 + ... + n = n(n + 1)/2")
print(f"  base n = 0: sum {total(0)}, formula {0 * 1 // 2}")
for n in range(1, 5):
    print(f"  step to n = {n}: {total(n - 1)} + {n} = {total(n)}, formula {n * (n + 1) // 2}")

print("1 + 3 + ... + (2n - 1) = n^2")
print(f"  base n = 1: sum {odd_total(1)}, formula {1 ** 2}")
for n in range(2, 6):
    print(f"  step to n = {n}: {odd_total(n - 1)} + {2 * n - 1} = {odd_total(n)}, formula {n ** 2}")

print("1 + 2 + ... + 2^n = 2^(n + 1) - 1")
print(f"  base n = 0: sum {power_total(0)}, formula {2 ** 1 - 1}")
for n in range(1, 5):
    print(f"  step to n = {n}: {power_total(n - 1)} + {2 ** n} = {power_total(n)}, formula {2 ** (n + 1) - 1}")

