def base(kind):
    if kind == 1 or kind == 3:
        return 0
    return 1


def term(kind, n):
    if kind == 1:
        return n
    if kind == 2:
        return 2 * n - 1
    if kind == 3:
        return 2 ** n
    return 2 * n


def S(kind, n):
    if n == base(kind):
        return term(kind, n)
    return S(kind, n - 1) + term(kind, n)


def formula(kind, n):
    if kind == 1:
        return n * (n + 1) // 2
    if kind == 2:
        return n * n
    if kind == 3:
        return 2 ** (n + 1) - 1
    return n * (n + 1)


count = int(input())
for i in range(count):
    kind = int(input())
    n = int(input())
    print(f"Problem {i + 1}: kind {kind}, n = {n}")
    if n == base(kind):
        print(f"  base: S({n}) = {S(kind, n)}")
    else:
        print(f"  step: S({n - 1}) + {term(kind, n)} = {S(kind, n - 1)} + {term(kind, n)} = {S(kind, n)}")
    print(f"  formula: {formula(kind, n)}")

