def fact(n):
    if n == 0:
        return 1
    return n * fact(n - 1)


def study(name, left, right, top):
    print(name)
    for n in range(top + 1):
        print(f"  n = {n}: {left(n)} vs {right(n)}, holds: {left(n) > right(n)}")
    b = top
    while b > 0 and left(b - 1) > right(b - 1):
        b = b - 1
    print(f"  base: n = {b}, and it holds from there to {top}")


def two_power(n):
    return 2 ** n


def square(n):
    return n * n


def hundred(n):
    return 100 * n


study("n! > 2^n (Example 3)", fact, two_power, 6)
study("2^n > n^2 (Example 5)", two_power, square, 7)
study("2^n > 100n (Example 7)", two_power, hundred, 12)

def factor(n, indent):
    d = 2
    while d * d <= n:
        if n % d == 0:
            print(f"{indent}{n} = {d} * {n // d}")
            return factor(d, f"{indent}  ") + factor(n // d, f"{indent}  ")
        d = d + 1
    print(f"{indent}{n} is prime")
    return [n]


def pay(n):
    if n == 12:
        return (3, 0)
    if n == 13:
        return (2, 1)
    if n == 14:
        return (1, 2)
    if n == 15:
        return (0, 3)
    fours, fives = pay(n - 4)
    return (fours + 1, fives)


for n in [360, 97, 221]:
    print(f"factor {n}:")
    print(f"result {factor(n, '  ')}")

for n in [12, 15, 16, 23]:
    fours, fives = pay(n)
    print(f"{n} cents: {fours} fours and {fives} fives, check {4 * fours + 5 * fives}")

